// 2. Hai nút phía trên: Mở app & Link Play Store (Side by Side)
Row(
    modifier = Modifier.fillMaxWidth(),
    horizontalArrangement = Arrangement.spacedBy(10.dp),
) {
    Button(
        onClick = {
            val pkg = camp.packageName
            val launchIntent = try {
                context.packageManager.getLaunchIntentForPackage(pkg)
            } catch (_: Exception) { null }

            if (launchIntent != null) {
                try {
                    launchIntent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                    context.startActivity(launchIntent)
                    actualViewModel.recordTestStart()
                    return@Button
                } catch (_: Exception) {}
            }
            Toast.makeText(context, context.getString(R.string.mission_not_installed_hint), Toast.LENGTH_LONG).show()
        },
        modifier = Modifier.weight(1f),
        shape = RoundedCornerShape(12.dp),
        colors = ButtonDefaults.buttonColors(
            containerColor = MaterialTheme.colorScheme.primary,
            contentColor = MaterialTheme.colorScheme.onPrimary,
        ),
    ) {
        Icon(
            imageVector = Icons.Default.PlayArrow,
            contentDescription = null,
            modifier = Modifier.size(18.dp),
        )
        Spacer(Modifier.width(6.dp))
        Text(
            text = stringResource(R.string.mission_report_open_app_btn),
            style = MaterialTheme.typography.labelLarge,
            fontWeight = FontWeight.Bold,
            maxLines = 1,
        )
    }

    OutlinedButton(
        onClick = {
            val pkg = camp.packageName
            try {
                val marketIntent = Intent(Intent.ACTION_VIEW, Uri.parse("market://details?id=$pkg")).apply {
                    setPackage("com.android.vending")
                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                }
                context.startActivity(marketIntent)
            } catch (_: Exception) {
                val fallbackUrl = camp.testingUrl.ifBlank { camp.playUrl }.ifBlank { "https://play.google.com/store/apps/details?id=$pkg" }
                try {
                    context.startActivity(Intent(Intent.ACTION_VIEW, Uri.parse(fallbackUrl)).apply {
                        addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                    })
                } catch (_: Exception) {}
            }
        },
        modifier = Modifier.weight(1f),
        shape = RoundedCornerShape(12.dp),
    ) {
        Icon(
            imageVector = Icons.Default.Shop,

metadata.preview:
